"use client";
import { useEffect, useState } from "react";

const STORAGE_KEY = "data_analytics_test_state_v1";

export default function DataAnalyticsTest() {
  /* ---------------- STATES ---------------- */
  const [step, setStep] = useState("login"); // login | instructions | test | submitted
  const [timer, setTimer] = useState(20 * 60);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [tabViolated, setTabViolated] = useState(false);

  /* ---------------- DATA ANALYTICS QUESTION BANK ---------------- */
  const questionBank = [
    {
      id: 1,
      question: "Which tool is commonly used for data visualization?",
      options: ["Excel", "Python", "Tableau", "All of the above"],
      correct: "All of the above",
    },
    {
      id: 2,
      question: "What does SQL stand for?",
      options: [
        "Structured Query Language",
        "Simple Query Language",
        "Sequential Query Logic",
        "None of the above",
      ],
      correct: "Structured Query Language",
    },
    {
      id: 3,
      question: "Which Python library is mainly used for data analysis?",
      options: ["NumPy", "Pandas", "Matplotlib", "TensorFlow"],
      correct: "Pandas",
    },
    {
      id: 4,
      question: "What is a primary key in a database?",
      options: [
        "A key that can be null",
        "A unique identifier",
        "A foreign key",
        "An index",
      ],
      correct: "A unique identifier",
    },
    {
      id: 5,
      question: "Which chart is best for showing trends over time?",
      options: ["Pie Chart", "Bar Chart", "Line Chart", "Histogram"],
      correct: "Line Chart",
    },
    {
      id: 6,
      question: "Which SQL clause is used to filter records?",
      options: ["WHERE", "GROUP BY", "ORDER BY", "HAVING"],
      correct: "WHERE",
    },
    {
      id: 7,
      question: "What does ETL stand for?",
      options: [
        "Extract, Transform, Load",
        "Export, Transfer, Load",
        "Extract, Test, Load",
        "Evaluate, Transform, Load",
      ],
      correct: "Extract, Transform, Load",
    },
    {
      id: 8,
      question: "Which data type stores textual data?",
      options: ["INT", "FLOAT", "VARCHAR", "BOOLEAN"],
      correct: "VARCHAR",
    },
    {
      id: 9,
      question: "Which measure shows the average value?",
      options: ["Median", "Mode", "Mean", "Range"],
      correct: "Mean",
    },
    {
      id: 10,
      question: "Which process removes duplicate data?",
      options: ["Data Mining", "Data Cleaning", "Data Modeling", "Data Storage"],
      correct: "Data Cleaning",
    },
    // 👉 Add more questions up to 200
  ];

  /* ---------------- LOAD SAVED STATE ---------------- */
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const data = JSON.parse(saved);
      setStep(data.step);
      setTimer(data.timer);
      setQuestions(data.questions || []);
      setAnswers(data.answers || {});
    }
  }, []);

  /* ---------------- SAVE STATE ---------------- */
  useEffect(() => {
    if (step === "test") {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ step, timer, questions, answers })
      );
    }
  }, [step, timer, questions, answers]);

  /* ---------------- RANDOM QUESTIONS ---------------- */
  const generateQuestions = () => {
    const shuffled = [...questionBank].sort(() => 0.5 - Math.random());
    setQuestions(shuffled.slice(0, 50));
  };

  /* ---------------- TIMER ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const interval = setInterval(() => {
      setTimer((prev) => {
        if (prev <= 1) {
          submitTest(true);
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [step]);

  /* ---------------- SECURITY ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const block = (e) => e.preventDefault();
    document.addEventListener("copy", block);
    document.addEventListener("paste", block);
    document.addEventListener("contextmenu", block);

    const visibilityHandler = () => {
      if (document.hidden && !tabViolated) {
        setTabViolated(true);
        alert("Tab switching detected. Test will be submitted.");
        submitTest(true);
      }
    };

    document.addEventListener("visibilitychange", visibilityHandler);

    return () => {
      document.removeEventListener("copy", block);
      document.removeEventListener("paste", block);
      document.removeEventListener("contextmenu", block);
      document.removeEventListener("visibilitychange", visibilityHandler);
    };
  }, [step, tabViolated]);

  /* ---------------- SUBMIT ---------------- */
  const submitTest = (forced = false) => {
    if (!forced && Object.keys(answers).length < questions.length) {
      alert("Please answer all questions.");
      return;
    }
    localStorage.removeItem(STORAGE_KEY);
    setStep("submitted");
  };

  /* ---------------- TIMER FORMAT ---------------- */
  const minutes = String(Math.floor(timer / 60)).padStart(2, "0");
  const seconds = String(timer % 60).padStart(2, "0");

  /* ---------------- LOGIN PAGE ---------------- */
  if (step === "login") {
    return (
      <CenteredCard title="Data Analytics Online Assessment">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            setStep("instructions");
          }}
          className="space-y-4"
        >
          <Input placeholder="Full Name" />
          <Input placeholder="Email ID" />
          <Input placeholder="Mobile Number" />
          <Input placeholder="College / Company" />
          <PrimaryButton>Proceed to Instructions</PrimaryButton>
        </form>
      </CenteredCard>
    );
  }

  /* ---------------- INSTRUCTIONS PAGE ---------------- */
  if (step === "instructions") {
    return (
      <CenteredCard title="Test Instructions">
        <div className="space-y-3 text-sm text-gray-700">
          <Instruction>50 questions – all mandatory</Instruction>
          <Instruction>Time limit: 20 minutes</Instruction>
          <Instruction>Copy / Paste disabled</Instruction>
          <Instruction>Tab switching not allowed</Instruction>
          <Instruction>Auto submit on timeout</Instruction>
        </div>

        <PrimaryButton
          className="mt-6"
          onClick={() => {
            generateQuestions();

            localStorage.setItem(
              STORAGE_KEY,
              JSON.stringify({
                step: "test",
                timer: 20 * 60,
                questions,
                answers: {},
              })
            );

            window.open("/test/data-analytics", "_blank");
          }}
        >
          Start Test
        </PrimaryButton>
      </CenteredCard>
    );
  }

  /* ---------------- TEST PAGE ---------------- */
  if (step === "test") {
    return (
      <div className="min-h-screen bg-gray-100 px-3 py-4">
        <div className="sticky top-0 bg-white p-4 rounded-xl shadow flex justify-between">
          <h2 className="font-bold">Data Analytics Test</h2>
          <span className="bg-red-100 text-red-600 px-3 py-1 rounded-full">
            ⏱ {minutes}:{seconds}
          </span>
        </div>

        <div className="max-w-3xl mx-auto mt-4">
          {questions.map((q, i) => (
            <div key={q.id} className="bg-white p-4 rounded-xl shadow mb-4">
              <p className="font-semibold mb-3">
                {i + 1}. {q.question}
              </p>

              <div className="grid gap-2">
                {q.options.map((opt) => (
                  <button
                    key={opt}
                    onClick={() =>
                      setAnswers((prev) => ({ ...prev, [q.id]: opt }))
                    }
                    className={`px-4 py-2 rounded border text-left ${
                      answers[q.id] === opt
                        ? "bg-blue-600 text-white"
                        : "hover:bg-blue-50"
                    }`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}

          <button
            onClick={() => submitTest()}
            className="w-full bg-green-600 text-white py-3 rounded-xl font-bold"
          >
            Submit Test
          </button>
        </div>
      </div>
    );
  }

  /* ---------------- SUBMITTED ---------------- */
  return (
    <CenteredCard title="Test Submitted 🎉">
      <p className="text-center text-gray-600">
        Thank you for attending the assessment.
      </p>
    </CenteredCard>
  );
}

/* ---------------- UI HELPERS ---------------- */

const CenteredCard = ({ title, children }) => (
  <div className="min-h-screen flex items-center justify-center bg-gray-100 px-3">
    <div className="bg-white p-6 rounded-2xl shadow w-full max-w-lg">
      <h2 className="text-xl font-bold text-center mb-5">{title}</h2>
      {children}
    </div>
  </div>
);

const Input = ({ placeholder }) => (
  <input
    required
    placeholder={placeholder}
    className="w-full border px-3 py-2 rounded-lg focus:ring-2 focus:ring-blue-500"
  />
);

const PrimaryButton = ({ children, onClick, className = "" }) => (
  <button
    onClick={onClick}
    className={`w-full bg-blue-600 text-white py-2 rounded-lg font-semibold ${className}`}
  >
    {children}
  </button>
);

const Instruction = ({ children }) => (
  <div className="flex gap-2">
    <span className="text-blue-600 font-bold">•</span>
    <span>{children}</span>
  </div>
);
